function caughtRain(heights: number[]): number {
  const n = heights.length;
  const left = new Array(n), right = new Array(n);
  for (let i = 0; i < n; i++) left[i] = Math.max(heights[i], i > 0 ? left[i - 1] : 0);
  for (let i = n - 1; i >= 0; i--) right[i] = Math.max(heights[i], i < n - 1 ? right[i + 1] : 0);
  let total = 0;
  for (let i = 0; i < n; i++) total += Math.min(left[i], right[i]) - heights[i];
  return total;
}

