class Solution:
    def caughtRain(self, heights: List[int]) -> int:
        n = len(heights)
        left, right = [0] * n, [0] * n
        for i in range(n):
            left[i] = max(heights[i], left[i - 1] if i > 0 else 0)
        for i in range(n - 1, -1, -1):
            right[i] = max(heights[i], right[i + 1] if i < n - 1 else 0)
        return sum(min(left[i], right[i]) - heights[i] for i in range(n))

